type ledger struct {
	mu    sync.Mutex
	file  *os.File
	total int
	size  int64 // length of the durable, acknowledged prefix of the file
}

// rollback discards any bytes written past the durable prefix after a failed
// write or fsync, so a later ADD cannot be appended after a half-written entry.
func (l *ledger) rollback() {
	_ = l.file.Truncate(l.size)
	_, _ = l.file.Seek(l.size, 0)
	_ = l.file.Sync()
}
